//! Actual BuildHost PrepareQuery with one retained Db and genuine prefix model.
use super::*;use super::analysis_context_tests::{fixture,run,current};use crate::policy_request::{AnalysisContext,WorkspaceAuxiliaryQuestion as Q};
#[test]fn actual_original_analyze_primary_prefix_stages_real_partial_model_not_semantic_none_and_refuses_checker_role(){
 let text="/datum/kept\n    var/before\n/proc/good()\n    return 1\n/datum/prefix\n    var/datum/first, second\n/proc/after()\n    return 2\n";
 let(mut host,mut request,root)=fixture(text);let intent=request.policy_inputs.as_mut().unwrap();intent.analysis_context=Some(AnalysisContext::OriginalAnalyze0290);intent.workspace_auxiliary=vec![Q::StoredRefs];intent.workspace.as_mut().unwrap().recursive_roots=vec![root.join("code")];let db=Arc::clone(host.query_db());run(&mut host,&request);
 let first=current(&host,|snapshot|{assert_eq!(snapshot.model_preparation,Some(dm_tree::frontend::DiagnosticPreparationPurpose::OriginalAnalyzePrefix));snapshot.require_analysis_context(Some(AnalysisContext::OriginalAnalyze0290)).unwrap();assert!(snapshot.require_analysis_context(Some(AnalysisContext::OriginalChecker0290)).is_err());assert!(snapshot.require_analysis_context(None).is_err());assert!(snapshot.analysis_subject.is_some());assert!(snapshot.tree.symbols().text(dm_ir::SymbolId::of("first")).is_some());assert!(snapshot.tree.symbols().text(dm_ir::SymbolId::of("second")).is_none());assert!(snapshot.tree.symbols().text(dm_ir::SymbolId::of("after")).is_none());let archive=snapshot.body_archive.as_ref().unwrap();assert_eq!(archive.len(),1);archive.parse_checked(0).unwrap();assert!(snapshot.resolved.is_none());assert!(snapshot.replay_proof.is_none());Arc::clone(&snapshot.tree)});let computed=db.db().stats(dm_query::Kind(4)).computed;run(&mut host,&request);current(&host,|snapshot|{assert!(Arc::ptr_eq(&first,&snapshot.tree));snapshot.body_archive.as_ref().unwrap().parse_checked(0).unwrap();});assert_eq!(db.db().stats(dm_query::Kind(4)).computed,computed);assert!(Arc::ptr_eq(&db,host.query_db()));
 let mut checker=request;checker.policy_inputs.as_mut().unwrap().analysis_context=Some(AnalysisContext::OriginalChecker0290);checker.policy_inputs.as_mut().unwrap().workspace_auxiliary.clear();assert!(crate::request_runner::run_build_with_host(checker,&mut host).is_err(),"checker purpose never treats authentic prefix as complete graph");
}
